import{_ as e,o as t,a as o,c}from"./app.BZuKQ50m.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算","link":"/api/SIMD-API/c_api/cube_compute/cube_compute"},{"text":"矩阵计算分形介绍","link":"/api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/cube_compute_fractal_intro"},{"text":"背景与核心概念","link":"/api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts.md","filePath":"api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts.md","lastUpdated":1789544578000}'),n={name:"api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts.md"};function _(r,a,p,u,l,i){return t(),o("div",null,[...a[0]||(a[0]=[c("div",null,[c("article",{class:"markdown-body"},[c("h1",null,"背景与核心概念"),c("p",null,"矩阵计算单元采用分块计算逻辑，例如可并行处理16×16的矩阵分片。在传统的线性存储布局（如row major（行主序）或column major（列主序））中，数据按行或列连续存放。当需要读取一个16×16的矩形数据块时，若直接从内存中获取，则需访问不连续的多个内存地址以逐行“收集”数据，这种非连续访问会导致内存效率显著下降。"),c("p",null,"为解决上述问题，引入了矩阵分形存储格式。该格式通过软件层对数据进行重排，使每个16×16计算块在物理内存中连续存放。硬件仅需发起一次连续读取，即可将整个数据块加载至片上寄存器，避免了多地址寻址开销，从而大幅提升矩阵计算单元的数据吞吐率。"),c("p",null,"昇腾AI处理器的矩阵计算单元为追求极高的数据吞吐率与计算密度，采用了专有的硬件架构设计。与通用CPU常用的连续线性存储不同，该单元要求输入输出数据必须符合特定的分形存储格式。在使用Ascend C的asc_mmad类接口进行算子开发时，深入理解这些数据格式对于实现正确的数据搬运、分块及性能优化至关重要。"),c("p",null,"为便于理解与记忆，文档采用“大Y小x”的直观命名法："),c("ul",null,[c("li",null,"大Y（Z/N）：表示分形矩阵之间的排列顺序（Z为row major（行主序），N为column major（列主序））。"),c("li",null,"小x（z/n）：表示分形矩阵内部元素的排列顺序（z为row major（行主序），n为column major（列主序））。")])])],-1)])])}const d=e(n,[["render",_]]);export{s as __pageData,d as default};
